script:
frappe.ui.form.on('Payment Entry', {
    setup: function(frm) {
        frm.set_query('custom_doctype_orokalipso', function() {
            return {
                filters: {
                    name: ['in', ['Analizar puro', 'Cambios']] // Filtro para la lista de doctypes
                }
            };
        });
    }
});

function redondeo2(num, decimalPlaces = 2) {
    var p = Math.pow(10, decimalPlaces);
    var n = (num * p) * (1 + Number.EPSILON);
    return Math.round(n) / p;
}

// Función reutilizable para calcular factor de comisión
function calcularYActualizarValores(frm, campoModificado = null) {
    let d = frm.doc;

    // Calcular el factor según las condiciones
    let factor = 0;
    if (d.comision_cobrada === 1) {
        factor = -1;
    } else if (d.comision_pagada === 1) {
        factor = 1;
    }

    // Validar valores iniciales
    let total = d.total_neto || 0;
    let comision = d.comision || 0;
    let comision_porcentual = d.comision_porcentual || 0;

    // Actualizar los valores dinámicamente según el campo modificado
    if (campoModificado === "comision_porcentual") {
        // Recalcular comisión basado en comision_porcentual
        comision = total === 0 ? 0 : redondeo2((comision_porcentual * total) / 100);
        frm.set_value("comision", comision);
    } else if (campoModificado === "comision") {
        // Recalcular comision_porcentual basado en comisión
        comision_porcentual = total === 0 ? 0 : redondeo2((comision * 100) / total);
        frm.set_value("comision_porcentual", comision_porcentual);
    }

    // Calcular el total a pagar
    let total_pagar = total + (factor * comision);
    frm.set_value("total_pagar", total_pagar);

    // Calcular lo que queda por pagar
    let total_pagado = d.total_pagado || 0;
    let queda_por_pagar = total_pagar - total_pagado;
    frm.set_value("queda_por_pagar", queda_por_pagar);
}
//Fin Función reutilizable para calcular los valores relacionados con la comisión y el total

//funcion para actualizar valores en caso de eliminar una fila
function actualizarMontos(frm) {
    let d = frm.doc;

    // Calcular totales usando reduce
    let totalIngresos = (d.pagos_in || []).reduce((total, row) => total + (row.importe || 0), 0);
    let totalEgresos = (d.pagos_out || []).reduce((total, row) => total + (row.importe_pago || 0), 0);

    // Actualizar los valores calculados
    frm.set_value('total_neto', totalIngresos);
    frm.set_value('total_pagado', totalEgresos);
    calcularYActualizarValores(frm);
}
// FIN funcion para actualizar valores en caso de eliminar una fila

// Funcionamiento del documento
frappe.ui.form.on('Cambios', {
    
    onload: function(frm) {
        const applyFilter = (field, fieldname, queryFunc) => {
            frm.set_query(field, fieldname, queryFunc);  // Aquí pasamos los tres argumentos correctos
        };
        
        // Aplicamos el filtro a 'cuenta_de_ingreso' en la tabla 'pagos_in'
        applyFilter('cuenta_de_ingreso', 'pagos_in', function(doc, cdt, cdn) {
            let d = locals[cdt][cdn];
            let divisa = d.divisa_de_cambio;
            let ofic = frm.doc.acronimo_oficina;
        
            // Si 'divisa' es null o undefined, usa '%'
            if (!divisa) {
                divisa = '%';
            }
        
            return {
                'filters': [
                    ['Mode of Payment', 'mode_of_payment', 'like', '%(' + divisa + ')%'],
                    ['Mode of Payment', 'mode_of_payment', 'like', '%' + ofic + '%']
                ],
            };
        });
        
        // Aplicamos el filtro a 'cuenta_de_pago' en la tabla 'pagos_out'
        applyFilter('modo_de_pago', 'pagos_out', function(doc, cdt, cdn) {
            let d = locals[cdt][cdn];
            let divisa = d.divisa_de_pago;
            let ofic = frm.doc.acronimo_oficina;
        
            // Si 'divisa' es null o undefined, usa '%'
            if (!divisa) {
                divisa = '%';
            }
        
            return {
                'filters': [
                    ['Mode of Payment', 'mode_of_payment', 'like', '%(' + divisa + ')%'],
                    ['Mode of Payment', 'mode_of_payment', 'like', '%' + ofic + '%']
                ],
            };
        });

        applyFilter('destino_de_pago', 'pagos_out', (doc, cdt, cdn) => {
            let d = locals[cdt][cdn];
            let regex = new RegExp('\\(([^()]*[^()]*)\\)', 'g');
            let filtro = 'efectivo';
            let regex2 = new RegExp(filtro, 'i');
            let str = d.modo_de_pago;
            let cuenta = null;
            let persona = frm.doc.supplier;

            if (regex2.test(str)) {
                cuenta = regex.exec(str) || ['%', '%'];
                return {
                    'filters': [['Bank Account', 'account_name', 'like', '%' + filtro + '%']],
                };
            } else {
                cuenta = regex.exec(str) || ['%', '%'];
                return {
                    'filters': [
                        ['Bank Account', 'account_name', 'like', '%' + cuenta[0] + '%'],
                        ['Bank Account', 'party', 'like', '%' + persona + '%'],
                    ],
                };
            }
        });

        applyFilter('contacto', (doc) => {
            let filtro = doc.supplier || 'Seleccione Cliente';
            return {
                'filters': [['Dynamic Link', 'link_name', 'like', '%' + filtro + '%']],
            };
        });
    },
    
    comision_porcentual: function(frm) {
        calcularYActualizarValores(frm, "comision_porcentual");
    },

    comision: function(frm) {
            calcularYActualizarValores(frm, "comision");
    },

    comision_cobrada: function(frm) {
        calcularYActualizarValores(frm);
        if(frm.doc.comision_cobrada === 0 && frm.doc.comision_pagada === 0){
            frm.set_value("comision_porcentual", 0);
            frm.set_value("comision", 0);
        }
    },

    comision_pagada: function(frm) {
        calcularYActualizarValores(frm);
        if(frm.doc.comision_cobrada === 0 && frm.doc.comision_pagada === 0){
            frm.set_value("comision_porcentual", 0);
            frm.set_value("comision", 0);
        }
    },
    
    total_pagado: function(frm) {
        // Recalcular el valor restante por pagar cuando cambie 'total_pagado'
        calcularYActualizarValores(frm);
    },
    
    total_neto: function(frm) {
        // Recalcular valores relacionados cuando cambie 'total_neto'
        calcularYActualizarValores(frm);
    },

    supplier: function(frm) {
        // Obtener el saldo del cliente al momento de realizar la operacion.
        if (frm.doc.posting_date) {
            frappe.call({
                method: "erpnext.accounts.doctype.payment_entry.payment_entry.get_party_and_account_balance",
                args: {
                    company: frm.doc.company,
                    date: frm.doc.posting_date,
                    ptype: 'supplier',
                    pty: frm.doc.supplier,
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.run_serially([
                            () => frm.set_value("saldo_cliente", r.message.party_balance),
                        ]);
                    }
                },
            });
        }
        // Codigo para Mostrar el apodo del cliente
        
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Supplier",
                filters: {
                    name: frm.doc.supplier
                },
                fieldname: ['supplier_details']
            },
            callback: function(r) {
                if (r.message.supplier_details) {
                    frappe.run_serially([
                        () => frm.set_value("apodo", r.message.supplier_details),
                    ]);
                }else {frm.set_value("apodo", supplier)}
            },
        });

    },
    
    contacto: function(frm) {
                
        let contacto = frm.doc.contacto;                        //Contacto relacionado con el supplier
        frappe.call(
            {                                                   //llamada al metodo de servidor para obtener datos de contacto
                method:"frappe.client.get_value",
                args: {
                    doctype:"Contact",                          //documento de tipo Item
                        filters: {                                  //argumento para filtrado
                            name : contacto                  //filtrado por item code igua a "Viruta"
                        },
                    fieldname : ['mobile_no']                     //obtencion de unidad de medida predeterminada uom
                }, 
                callback: function(r) {                         //funcion callback
                   frm.set_value("nro_movil", r.message.mobile_no);        //Colocar el Nro de Tlf en el campo
    
                }
    	});
    },
    
    oficina: function(frm) {
        let oficina = frm.doc.oficina;
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Oficinas configuraciones",
                filters: {
                    name: oficina
                },
                fieldname: [
                            'acronimo',
                            'item_servicio_cambios',
                            'centro_costos_cambios'
                            ]
            },
            callback: function(r) {
                if (r.message) {
                    frappe.run_serially([
                        () => frm.set_value("acronimo_oficina", r.message.acronimo),
                        () => frm.set_value("item_servicio_cambios", r.message.item_servicio_cambios),
                        () => frm.set_value("centro_costos_cambios", r.message.centro_costos_cambios),
                    ]);
                }else {frappe.throw('Error De Configuracion');}
            },
        });
        
    },
    
    recibido_ext: function(frm) {
        const applyFilter = (field, fieldname, queryFunc) => {
        frm.set_query(field, fieldname, queryFunc);  // Aquí pasamos los tres argumentos correctos
        };
        
        // Aplicamos el filtro a 'cuenta_de_ingreso' en la tabla 'pagos_in'
        applyFilter('cuenta_de_ingreso', 'pagos_in', function(doc, cdt, cdn) {
            let d = locals[cdt][cdn];
            let divisa = d.divisa_de_cambio;
            let ofic = frm.doc.acronimo_oficina;
            if(frm.doc.recibido_ext == 1){
                ofic = "ext";
            }
        
            // Si 'divisa' es null o undefined, usa '%'
            if (!divisa) {
                divisa = '%';
            }
        
            return {
                'filters': [
                    ['Mode of Payment', 'mode_of_payment', 'like', '%(' + divisa + ')%'],
                    ['Mode of Payment', 'mode_of_payment', 'like', '%' + ofic + '%']
                ],
            };
        });
        
        
    },

    refresh: function(frm) {
        const addCustomButton = (label, method) => {
            frm.add_custom_button(__(label), function() {
                frappe.call({
                    method: method,
                    args: { documento: frm.doc },
                    callback: function(r) {
                        console.log(r.message);
                    }
                });
            });
        };

        addCustomButton("Test", 'testpayment');
        addCustomButton("Test2", 'test');
    },
});
// Fin del funcionamiento del documento

// Tabla Pagos in
frappe.ui.form.on('Cambios pagos in', {
    divisa_de_cambio: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        const day = row.fecha_pago;

        frappe.call({
            method: "erpnext.setup.utils.get_exchange_rate",
            args: {
                from_currency: 'USD',
                to_currency: row.divisa_de_cambio,
                transaction_date: day,
            },
            callback: (r) => {
                let tasa_de_cambio = redondeo2(r.message, 9);
                row.tasa_de_cambio = tasa_de_cambio;
                refresh_field(row);
            },
        });

        row.cuenta_de_ingreso = '';
        calcularImporteYActualizarTotalNeto(frm, row);
        calcularYActualizarValores(frm, "comision_porcentual");
    },

    cantidad: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calcularImporteYActualizarTotalNeto(frm, row);
        calcularYActualizarValores(frm, "comision_porcentual");
    },

    tasa_de_cambio: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calcularImporteYActualizarTotalNeto(frm, row);
        calcularYActualizarValores(frm, "comision_porcentual");
    },
        
    pagos_in_remove: function(frm, cdt, cdn) {
        actualizarMontos(frm);
    },
});
//Fin tabla pagos in

// Tabla pagos out
frappe.ui.form.on('Cambios pagos out', {
    divisa_de_pago: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        const day = row.fecha_pago;

        frappe.call({
            method: "erpnext.setup.utils.get_exchange_rate",
            args: {
                from_currency: 'USD',
                to_currency: row.divisa_de_pago,
                transaction_date: day,
            },
            callback: (r) => {
                let tasa_de_cambio = redondeo2(r.message, 9);
                row.tasa_de_pago = tasa_de_cambio;
                refresh_field(row);
            },
        });

        row.destino_de_pago = '';
        calcularImporteYActualizarTotalPagado(frm, row);
    },

    cantidad_pagado: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calcularImporteYActualizarTotalPagado(frm, row);
    },

    tasa_de_pago: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        calcularImporteYActualizarTotalPagado(frm, row);
    },

    pagos_out_remove: function(frm, cdt, cdn) {
        actualizarMontos(frm);
    },
});
//Fin tabla pagos out

// Función para calcular importe y actualizar el total neto
function calcularImporteYActualizarTotalNeto(frm, row) {
    let cantidad = row.cantidad;
    let tasa = row.tasa_de_cambio;

    if (tasa !== 0) {
        let importe = redondeo2(cantidad / tasa);
        row.importe = importe;
        refresh_field(row);
        
        // Actualizar total neto
        let pagos_in = frm.doc.pagos_in;
        let total = pagos_in.reduce((acc, item) => acc + item.importe, 0);
        frm.set_value("total_neto", total);

        if (frm.doc.comision_cobrada === 0 && frm.doc.comision_pagada === 0) {
            frm.set_value("total_pagar", total);
        }
    }
}

// Función para calcular importe y actualizar el total pagado
function calcularImporteYActualizarTotalPagado(frm, row) {
    let cantidad = row.cantidad_pagado;
    let tasa = row.tasa_de_pago;

    if (tasa !== 0) {
        let importe = redondeo2(cantidad / tasa);
        row.importe_pago = importe;
        refresh_field(row);

        // Actualizar total pagado
        let pagos_out = frm.doc.pagos_out;
        let total = pagos_out.reduce((acc, item) => acc + item.importe_pago, 0);
        frm.set_value("total_pagado", total);
    }
}

function redondeo2(num, decimalPlaces = 2) //funcion de apoyo para optimizar los calculos
{
    var p = Math.pow(10, decimalPlaces);
    var n = (num * p) * (1 + Number.EPSILON);
    return Math.round(n) / p;
}
// termino de la funcion.

// Función para calcular importe y actualizar el total neto
function calcularImporteYActualizarTotalNeto(frm, row) {
    let cantidad = row.importe_pagado;
    let tasa = row.tasa_de_pago;
    let pendiente = frm.doc.divisas_predeterminado;

    if (tasa !== 0) {
        let importe = redondeo2(cantidad / tasa);
        row.importe_pago = importe;
        refresh_field(row);
        
        // Actualizar total neto
        let pagos = frm.doc.analizar_puro_pagos;
        let total = pagos.reduce((acc, item) => acc + item.importe_pago, 0);
        frm.set_value("monto_cobrado", total);
        pendiente = pendiente - total;
        frm.set_value("pendiente", pendiente);
        
    }
}
// FIN Función para calcular importe y actualizar el total neto

//Funcion actualizar el pediente si se borra una fila
function actualizarImporteYPendiente(frm) {
    let pendiente = frm.doc.divisas_predeterminado;

    // Actualizar total neto
    let pagos = frm.doc.analizar_puro_pagos;
    let total = pagos.reduce((acc, item) => acc + item.importe_pago, 0);
    frm.set_value("monto_cobrado", total);
    pendiente = pendiente - total;
    frm.set_value("pendiente", pendiente);
        
}
//FIN funcion actualizar el pediente si se borra una fila

//validacion antes de guardar
frappe.ui.form.on('Analizar Puro', {                                 //validacion antes de guardar
	before_save: function(frm)
	{
	    //validacion de datos y calculos
	    let peso0 = redondeo2(frm.doc.peso_sin_fundir);             //se toma el peso sin fundir
        let en_oficina = frm.doc.en_oficina;
        if(en_oficina == 0)
        {
            
            frm.set_value("peso_fundido", peso0);                   //se toma el peso del campo peso sin fundir si no se realizo la fundicion en la oficina

        }
	    
	    let peso1 = redondeo2(frm.doc.peso_fundido);                    //se toma el peso fundido
	    let merma = redondeo2(frm.doc.porc_merma);                      //se toma la merma
	    let ley0 = redondeo2(frm.doc.ley_analitica);                    //se toma la ley analitica
	    let ley1 = redondeo2(frm.doc.ley_recuperable);                  //se toma la ley recuperable
	    let puras = redondeo2(frm.doc.puras_en_gr);                     //se toma el valor de las puras
	    let merma_validada = redondeo2((((peso1-peso0)/peso0)*100));    //se calcula la merma para una posterior validacion
	    let ley1_validada = redondeo2(ley0 -5);                         //se calcula la nueva ley recuperable para una posterior validacion
	    let puras_validada = redondeo2((peso1*ley1)/1000);              //se calcula el valor de las puras para una posterior validacion
	    let nro_calculos = frm.doc.nro_de_calculos;                     //se verifica el nro de calculos realizados
            
	    if(ley1_validada != ley1 || puras_validada != puras || merma != merma_validada || nro_calculos == 0 || ley1_validada < 100) //se validan los datos calculados que toman en cuenta todos los campos a guardar
	    {
	        frappe.throw(                                       //se causa un error en el sismeta y se muestra un mensaje en pantalla.
                'Valide los datos introducidos y presione el Boton "Calcular" si esta satisfecho entonces guarde el documento'
                );    
	    }
	    
	     //caso principal Analisis Costo cero en cero
        if (frm.doc.costo_cero == 0){
            //Caso en que no seleccionen ningun tipo de cobro
            if(frm.doc.cobro_en_divisas ==0 && frm.doc.cobro_en_virutas == 0){
                frappe.throw(
                    'Seleccione algun metodo de cobro .<br>' +
                    'Verifique el tipo de cobro a implementar.'
                );
            }

            //entoncs evaluo los montos
            //Caso Cobro virutas y virutas cobradas 0
            if (frm.doc.cobro_en_virutas == 1 && frm.doc.virutas_cobradas == 0) {
                frappe.throw(
                    '-Se intenta guardar un análisis sin cobro alguno.<br>' +
                    '*-Si es Crédito, seleccione cobro en Divisas y marque crédito.<br>' +
                    '*-En caso de Análisis de costo cero marque la casilla correspondiente.<br>' + 
                    '*****Porfavor asegúrese de revisar los cobros...******'
                );
            }
            
            //Caso  Cobro en Divisas Monto Cobrado 0
            if (frm.doc.cobro_en_divisas == 1 && frm.doc.monto_cobrado == 0) {
                if (frm.doc.credito == 1){
                    //En caso de Ser credito verificacion del monto acreditado
                    if(frm.doc.divisas_predeterminado <= frm.doc.divisas_minimo){
                        frappe.throw(
                            'Se encontro un error en el cobro.<br>'+
                            'Asegurese de revisar los cobros...<br>' + 'Monto minimo  : ' + frm.doc.divisas_minimo
                        );
                    }
                    return;
                }
                // en Caso de no ser Credito debe ingresar un monto
                frappe.throw(
                    '-Se intenta guardar un análisis sin cobro alguno.<br>' +
                    '*-Si es Crédito, seleccione cobro en Divisas y marque crédito.<br>' +
                    '*-En caso de Análisis de costo cero marque la casilla correspondiente.<br>' + 
                    '*****Porfavor asegúrese de revisar los cobros...******'
                );
            }

        }
	}
	
});
// FIN Validacion de datos

//Funcionamiento del documento
frappe.ui.form.on('Analizar Puro', {
	
    onload: function(frm) {
        //funcion de aplicacion de filtros
        const applyFilter = (field, fieldname, queryFunc) => {
        frm.set_query(field, fieldname, queryFunc);  // Aquí pasamos los tres argumentos correctos para resolver el contacto del supplier
        };
                                                //Aplicaciones de filtros
        //filtro para contacto relacionado con supplier
        applyFilter('contacto', (doc) => {
            let filtro = doc.supplier || 'Seleccione Cliente';
            return {
            'filters': [['Dynamic Link', 'link_name', 'like', filtro]],
            };
        });
        
        //filtro para almacen de virutas
        applyFilter('almacen_predeterminado', (doc) => {
            let filtro = "viruta" || 'Seleccione Almacen';
            return {
            'filters': [["Warehouse","name","like","%" + filtro + "%"]],
            };
        });
        
        //filtro para que muestre solo los metodos de pago de la divisa seleccionada
        applyFilter('modo_de_pago', 'analizar_puro_pagos', function(doc, cdt, cdn) {
            let d = locals[cdt][cdn];
            let divisa = d.divisa_de_pago;
        
            // Si 'divisa' es null o undefined, usa '%'
            if (!divisa) {
                divisa = '%';
            }
        
            return {
                'filters': [
                    ['Mode of Payment', 'mode_of_payment', 'like', '%(' + divisa + ')%'],
                ],
            };
        });
    },
    
    // Mostrar el saldo del cliente Seleccionado
    supplier: function(frm) {
        let supplier = frm.doc.supplier;
        if (frm.doc.posting_date) {
            frappe.call({
                method: "erpnext.accounts.doctype.payment_entry.payment_entry.get_party_and_account_balance",
                args: {
                    company: frm.doc.company,
                    date: frm.doc.posting_date,
                    ptype: 'supplier',
                    pty: frm.doc.supplier,
                },
                callback: function(r) {
                    if (r.message) {
                        frappe.run_serially([
                            () => frm.set_value("saldo_cliente", r.message.party_balance),
                        ]);
                    }
                },
            });
        }
        
        // Codigo para Mostrar el apodo del cliente
        frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Supplier",
                filters: {
                    name: supplier
                },
                fieldname: ['supplier_details']
            },
            callback: function(r) {
                if (r.message.supplier_details) {
                    frappe.run_serially([
                        () => frm.set_value("apodo", r.message.supplier_details),
                    ]);
                }else {frm.set_value("apodo", supplier)}
            },
        });
    },
    
    //Seleccion de Oficina
    oficina: function(frm){
        let oficina = frm.doc.oficina;
        frappe.call({
            method: "frappe.client.get_value",
            args: {
