function redondeo2(num, decimalPlaces = 2) {
    var p = Math.pow(10, decimalPlaces);
    var n = (num * p) * (1 + Number.EPSILON);
    return Math.round(n) / p;
}

// Función reutilizable para calcular factor de comisión
function calcularFactor(frm) {
    if (frm.doc.comision_cobrada === 1) {
        return -1;
    } else if (frm.doc.comision_pagada === 1) {
        return 1;
    } else {
        return 0;
    }
}

// Función reutilizable para calcular los valores relacionados con la comisión y el total
function actualizarValores(frm, factor) {
    let d = frm.doc;
    let total = d.total_neto;
    let comision_porcentual = total === 0 ? 0 : redondeo2(d.comision * 100 / total);
    frm.set_value("comision_porcentual", comision_porcentual);
    
    let total_pagar = total + (factor * d.comision);
    frm.set_value("total_pagar", total_pagar);
    
    let total_pagado = d.total_pagado;
    frm.set_value("queda_por_pagar", total_pagar - total_pagado);
}

